"""Routes for Runs, generated by Dryv; the engine implements RuntimeRunsService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Depends, Path, Query, Request

from mzizi_engine.api.schemas.api.runtime.models.event_list import EventList
from mzizi_engine.api.schemas.api.runtime.models.run_list import RunList
from mzizi_engine.api.schemas.mongo.runtime.enums.run_status import RunStatus
from mzizi_engine.api.schemas.mongo.runtime.models.run import Run

__all__ = ["RuntimeRunsService", "build_runtime_runs_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class RuntimeRunsService(ABC):
    """What Runs needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def get_run(self, *, run_id: UUID) -> Run:
        """One run with its status and the jobs it started."""

    @abstractmethod
    async def list_run_events(self, *, run_id: UUID, after: int | None, limit: int | None) -> EventList:
        """A run's events in order, optionally only those after a sequence number (for polling)."""

    @abstractmethod
    async def list_runs(self, *, status: RunStatus | None, limit: int | None) -> RunList:
        """Recent runs, newest first, optionally by status."""


def build_runtime_runs_router(service: RuntimeRunsService, guard: Guard | None = None) -> APIRouter:
    """Routes for Runs, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Runs"], dependencies=[Depends(guard)] if guard else [])

    @router.get(
        "/v1/runs/{runId}",
        response_model=Run,
        status_code=200,
        summary="One run with its status and the jobs it started.",
    )
    async def get_run(
        run_id: Annotated[UUID, Path(alias="runId")],
    ) -> Run:
        return await service.get_run(run_id=run_id)

    @router.get(
        "/v1/run-events",
        response_model=EventList,
        status_code=200,
        summary="A run\u0027s events in order, optionally only those after a sequence number (for polling).",
    )
    async def list_run_events(
        run_id: Annotated[UUID, Query(alias="runId")],
        after: Annotated[int | None, Query(alias="after")] = None,
        limit: Annotated[int | None, Query(alias="limit")] = None,
    ) -> EventList:
        return await service.list_run_events(run_id=run_id, after=after, limit=limit)

    @router.get(
        "/v1/runs",
        response_model=RunList,
        status_code=200,
        summary="Recent runs, newest first, optionally by status.",
    )
    async def list_runs(
        status: Annotated[RunStatus | None, Query(alias="status")] = None,
        limit: Annotated[int | None, Query(alias="limit")] = None,
    ) -> RunList:
        return await service.list_runs(status=status, limit=limit)

    return router
